def compute(vars):
    nonvested_stock_units = vars["v1"]
    total_share_based_compensation_expense = vars["v2"]

    if total_share_based_compensation_expense == 0:
        return None

    ratio = nonvested_stock_units / total_share_based_compensation_expense
    percentage = ratio * 100

    return {
        "value": percentage,
        "trace": {
            "nonvested_stock_units": nonvested_stock_units,
            "total_share_based_compensation_expense": total_share_based_compensation_expense,
            "ratio": ratio,
            "output_meta": {
                "currency": None,
                "scale": "ones",
                "unit": "percentage"
            }
        }
    }
